const crypto = require('crypto');

// Debug
console.log('Input item:', JSON.stringify($json, null, 2));

// Data input
const input = $json;

// Structure input
if (!input.kluczAPI || !input.fakturaData || !input.url) {
  console.error('Missing required fields in input:', input);
  return [{
    json: {
      error: 'Missing required fields',
      input: input
    }
  }];
}

try {
const kluczAPI = input.kluczAPI.trim();
const fakturaData = input.fakturaData;
const url = input.url;
const nazwaUsera = input.nazwaUsera;
const nazwaKlucza = input.nazwaKlucza;

// Convert hex key to buffer
const hexKey = Buffer.from(kluczAPI, 'hex');

// Generate request content and message
const requestContent = JSON.stringify(fakturaData);
const message = url + nazwaUsera + nazwaKlucza + requestContent;

// Create HMAC SHA1
const hash = crypto.createHmac('sha1', hexKey).update(message).digest('hex');

// Create auth header
const authHeader = `IAPIS user=${nazwaUsera}, hmac-sha1=${hash}`;

console.log('Generated hash:', hash);
console.log('Auth header:', authHeader);

// Resturn result
return {
  authentication: authHeader,
  requestData: fakturaData,
  url: url
};

} catch (error) {
  console.error("Error processing item:", error);
  return {
    error: error.message,
    input: input
  };
}

const items = $input.all();
const results = [];

// Mapowanie symboli kraju na pełne nazwy (case-insensitive)
const countryCodeToName = {
  CZ: 'Czechy',
  SK: 'Słowacja',
  HU: 'Węgry',
  RO: 'Rumunia',
  BG: 'Bułgaria',
  PL: 'Polska',
};

// Fallback: waluta -> kraj (używane tylko gdy brak danych o kraju)
const currencyToCountry = {
  CZK: 'Czechy',
  HUF: 'Węgry',
  RON: 'Rumunia',
};

for (const item of items) {
  // 1. Sprawdź kolumnę Kraj (zawiera symbol: CZ, SK, BG, etc.)
  const krajSymbol = (item.json['Kraj'] || item.json['Kraj kupującego'] || item.json['Symbol kraju kupującego'] || '').toString().toUpperCase().trim();

  // 2. Mapuj symbol na pełną nazwę
  let kraj = countryCodeToName[krajSymbol] || '';

  // 3. Fallback: waluta -> kraj (tylko dla walut jednoznacznych, NIE EUR)
  if (!kraj) {
    const waluta = (item.json['waluta obca [CZK, EUR, RON, HUF]'] || item.json['Waluta'] || '').toString().toUpperCase();
    kraj = currencyToCountry[waluta] || 'Słowacja'; // EUR domyślnie Słowacja
  }

  results.push({
    ...item.json,
    kraj: kraj,
  });
}

return results.map((item) => ({ json: item }));

